// Publishes the two canonical root-level llms artifacts to the site so the
// deployed domain serves them at /llms.txt and /llms-full.txt (GEO: AI
// engines fetch these for structured context). Run as a `prebuild` step so
// the published copies always come from the single source of truth
// (generated by scripts/generate_llms.py, `make llms`) — never committed into
// public/, never drifting.
//
// The per-area shards are not handled here: the generator writes them
// straight into site/public/llms/, which Astro serves verbatim at
// /llms/llms-<area>.txt, and prunes its own stale files. This step only has
// to publish the two root files and retire any shard a previous layout left
// at the public root, where it would keep serving text that llms.txt no
// longer links.
import { copyFileSync, existsSync, mkdirSync, readdirSync, rmSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const repoRoot = join(here, "..", "..");
const publicDir = join(here, "..", "public");

mkdirSync(publicDir, { recursive: true });

const published = ["llms.txt", "llms-full.txt"];

// Drop root-level llms artifacts this step no longer publishes: the per-area
// shards used to be copied here before they moved to public/llms/.
for (const name of readdirSync(publicDir)) {
  if (/^llms(-[a-z0-9-]+)?\.txt$/.test(name) && !published.includes(name)) {
    rmSync(join(publicDir, name));
    console.log(`[copy-llms] removed stale ${name}`);
  }
}

let copied = 0;
for (const name of published) {
  const src = join(repoRoot, name);
  if (!existsSync(src)) {
    console.warn(`[copy-llms] ${name} not found at repo root — run \`make llms\``);
    continue;
  }
  copyFileSync(src, join(publicDir, name));
  copied += 1;
}
console.log(`[copy-llms] published ${copied} llms artifacts -> site/public/`);
